mapper.select:
SELECT G.GROUP_ID
FROM GYE_GROUP G
WHERE G.GROUP_ID IN

      #{id}

  AND (
      G.OWNER_ID = #{memberId}
      OR EXISTS (
          SELECT 1
            FROM GYE_MEMBER MY
           WHERE MY.GROUP_ID = G.GROUP_ID
             AND MY.MEMBER_ID = #{memberId}
             AND MY.STATUS IN ('ACTIVE', 'EXPELLED')
      )
      OR EXISTS (
          SELECT 1
            FROM JOIN_REQUEST JR
           WHERE JR.GROUP_ID = G.GROUP_ID
             AND JR.MEMBER_ID = #{memberId}
             AND JR.STATUS = 'PENDING'
      )
  )

SELECT GM.GROUP_ID AS "groupId", ROUND((1 - AVG(RS.PROB)) * 100) AS "healthScore" FROM GYE_MEMBER GM LEFT JOIN ( SELECT MEMBER_ID, PROB, ROW_NUMBER() OVER ( PARTITION BY MEMBER_ID ORDER BY SCORED_AT DESC, RISK_SCORE_ID DESC ) AS RN FROM RISK_SCORE ) RS ON RS.MEMBER_ID = GM.MEMBER_ID AND RS.RN = 1 WHERE GM.STATUS = 'ACTIVE' AND GM.GROUP_ID IN
#{id}
GROUP BY GM.GROUP_ID

SELECT COUNT(*)
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}
  AND OWNER_ID = #{memberId}
